use crate::convert::AsPrimitive;

/// The `+` operator.
///
/// Implemented for [`Field`] and the integer types. `Field` addition is modulo the field's prime.
/// Integer addition fails if the result doesn't fit in the type, in both constrained and
/// unconstrained code; use [`WrappingAdd`] to wrap around instead.
///
/// Example:
///
/// ```noir
/// use std::ops::Add;
///
/// struct Point {
///     x: u32,
///     y: u32,
/// }
///
/// impl Add for Point {
///     fn add(self, other: Point) -> Point {
///         Point { x: self.x + other.x, y: self.y + other.y }
///     }
/// }
///
/// fn main() {
///     let p = Point { x: 1, y: 2 } + Point { x: 3, y: 4 };
///     assert_eq(p.x, 4);
///     assert_eq(p.y, 6);
/// }
/// ```
///
/// Integer overflow fails; use [`WrappingAdd`] to wrap around:
///
/// ```noir should_fail
/// // Fails: 256 doesn't fit in a `u8`.
/// let _ = 255_u8 + 1;
/// ```
// docs:start:add-trait
pub trait Add {
    /// Returns `self + other`.
    fn add(self, other: Self) -> Self;
}
// docs:end:add-trait

impl Add for Field {
    fn add(self, other: Field) -> Field {
        self + other
    }
}

impl Add for u128 {
    fn add(self, other: u128) -> u128 {
        self + other
    }
}
impl Add for u64 {
    fn add(self, other: u64) -> u64 {
        self + other
    }
}
impl Add for u32 {
    fn add(self, other: u32) -> u32 {
        self + other
    }
}
impl Add for u16 {
    fn add(self, other: u16) -> u16 {
        self + other
    }
}
impl Add for u8 {
    fn add(self, other: u8) -> u8 {
        self + other
    }
}
impl Add for i8 {
    fn add(self, other: i8) -> i8 {
        self + other
    }
}
impl Add for i16 {
    fn add(self, other: i16) -> i16 {
        self + other
    }
}
impl Add for i32 {
    fn add(self, other: i32) -> i32 {
        self + other
    }
}
impl Add for i64 {
    fn add(self, other: i64) -> i64 {
        self + other
    }
}

/// The binary `-` operator.
///
/// Implemented for [`Field`] and the integer types. `Field` subtraction is modulo the field's
/// prime, so `0 - 1` is the largest field element. Integer subtraction fails if the result doesn't
/// fit in the type, for example when an unsigned subtraction would go below zero; use
/// [`WrappingSub`] to wrap around instead.
///
/// Example:
///
/// ```noir
/// assert_eq(5_u8 - 3, 2);
///
/// // Field subtraction wraps around the prime.
/// let minus_one: Field = 0 - 1;
/// assert_eq(minus_one + 1, 0);
/// ```
///
/// Unsigned subtraction below zero fails:
///
/// ```noir should_fail
/// let zero: u8 = 0;
/// // Fails: -1 doesn't fit in a `u8`.
/// let _ = zero - 1;
/// ```
// docs:start:sub-trait
pub trait Sub {
    /// Returns `self - other`.
    fn sub(self, other: Self) -> Self;
}
// docs:end:sub-trait

impl Sub for Field {
    fn sub(self, other: Field) -> Field {
        self - other
    }
}

impl Sub for u128 {
    fn sub(self, other: u128) -> u128 {
        self - other
    }
}
impl Sub for u64 {
    fn sub(self, other: u64) -> u64 {
        self - other
    }
}
impl Sub for u32 {
    fn sub(self, other: u32) -> u32 {
        self - other
    }
}
impl Sub for u16 {
    fn sub(self, other: u16) -> u16 {
        self - other
    }
}
impl Sub for u8 {
    fn sub(self, other: u8) -> u8 {
        self - other
    }
}
impl Sub for i8 {
    fn sub(self, other: i8) -> i8 {
        self - other
    }
}
impl Sub for i16 {
    fn sub(self, other: i16) -> i16 {
        self - other
    }
}
impl Sub for i32 {
    fn sub(self, other: i32) -> i32 {
        self - other
    }
}
impl Sub for i64 {
    fn sub(self, other: i64) -> i64 {
        self - other
    }
}

/// The `*` operator.
///
/// Implemented for [`Field`] and the integer types. `Field` multiplication is modulo the field's
/// prime. Integer multiplication fails if the result doesn't fit in the type; use [`WrappingMul`] to
/// wrap around instead.
///
/// Example:
///
/// ```noir
/// assert_eq(4_u8 * 3, 12);
/// assert_eq(-4_i8 * 3, -12);
/// ```
///
/// A product that doesn't fit in the type fails; use [`WrappingMul`] to wrap around:
///
/// ```noir should_fail
/// // Fails: 256 doesn't fit in a `u8`.
/// let _ = 16_u8 * 16;
/// ```
// docs:start:mul-trait
pub trait Mul {
    /// Returns `self * other`.
    fn mul(self, other: Self) -> Self;
}
// docs:end:mul-trait

impl Mul for Field {
    fn mul(self, other: Field) -> Field {
        self * other
    }
}

impl Mul for u128 {
    fn mul(self, other: u128) -> u128 {
        self * other
    }
}
impl Mul for u64 {
    fn mul(self, other: u64) -> u64 {
        self * other
    }
}
impl Mul for u32 {
    fn mul(self, other: u32) -> u32 {
        self * other
    }
}
impl Mul for u16 {
    fn mul(self, other: u16) -> u16 {
        self * other
    }
}
impl Mul for u8 {
    fn mul(self, other: u8) -> u8 {
        self * other
    }
}
impl Mul for i8 {
    fn mul(self, other: i8) -> i8 {
        self * other
    }
}
impl Mul for i16 {
    fn mul(self, other: i16) -> i16 {
        self * other
    }
}
impl Mul for i32 {
    fn mul(self, other: i32) -> i32 {
        self * other
    }
}
impl Mul for i64 {
    fn mul(self, other: i64) -> i64 {
        self * other
    }
}

/// The `/` operator.
///
/// Implemented for [`Field`] and the integer types.
///
/// - For integers, the quotient is rounded toward zero, so `-7 / 2` is `-3`.
/// - For `Field`, `a / b` is the field element `c` with `c * b == a`: it multiplies by the inverse
///   of `b`, and doesn't round. `1 / 2` is not zero.
///
/// Dividing by zero fails, for `Field` as well as for integers. For a signed type, dividing the
/// minimum value by `-1` also fails, because the result doesn't fit. The remainder of integer
/// division is given by [`Rem`].
///
/// Example:
///
/// ```noir
/// assert_eq(7_u8 / 2, 3);
/// assert_eq(-7_i8 / 2, -3);
///
/// // Field division multiplies by the inverse.
/// let half: Field = 1 / 2;
/// assert_eq(half * 2, 1);
/// ```
///
/// Division by zero fails, for `Field` too:
///
/// ```noir should_fail
/// let zero: Field = 0;
/// // Fails: division by zero.
/// let _ = 1 / zero;
/// ```
// docs:start:div-trait
pub trait Div {
    /// Returns `self / other`.
    fn div(self, other: Self) -> Self;
}
// docs:end:div-trait

impl Div for Field {
    fn div(self, other: Field) -> Field {
        self / other
    }
}

impl Div for u128 {
    fn div(self, other: u128) -> u128 {
        self / other
    }
}
impl Div for u64 {
    fn div(self, other: u64) -> u64 {
        self / other
    }
}
impl Div for u32 {
    fn div(self, other: u32) -> u32 {
        self / other
    }
}
impl Div for u16 {
    fn div(self, other: u16) -> u16 {
        self / other
    }
}
impl Div for u8 {
    fn div(self, other: u8) -> u8 {
        self / other
    }
}
impl Div for i8 {
    fn div(self, other: i8) -> i8 {
        self / other
    }
}
impl Div for i16 {
    fn div(self, other: i16) -> i16 {
        self / other
    }
}
impl Div for i32 {
    fn div(self, other: i32) -> i32 {
        self / other
    }
}
impl Div for i64 {
    fn div(self, other: i64) -> i64 {
        self / other
    }
}

/// The `%` operator.
///
/// Implemented for the integer types; [`Field`] has no remainder. The result has the sign of the
/// left operand, matching [`Div`], which rounds toward zero: `-7 % 2` is `-1`. A zero divisor
/// fails.
///
/// Example:
///
/// ```noir
/// assert_eq(7_u8 % 4, 3);
/// assert_eq(-7_i8 % 2, -1);
/// assert_eq(7_i8 % -2, 1);
/// ```
///
/// A zero divisor fails:
///
/// ```noir should_fail
/// // Fails: division by zero.
/// let _ = 7_u8 % 0;
/// ```
// docs:start:rem-trait
pub trait Rem {
    /// Returns `self % other`.
    fn rem(self, other: Self) -> Self;
}
// docs:end:rem-trait

impl Rem for u128 {
    fn rem(self, other: u128) -> u128 {
        self % other
    }
}
impl Rem for u64 {
    fn rem(self, other: u64) -> u64 {
        self % other
    }
}
impl Rem for u32 {
    fn rem(self, other: u32) -> u32 {
        self % other
    }
}
impl Rem for u16 {
    fn rem(self, other: u16) -> u16 {
        self % other
    }
}
impl Rem for u8 {
    fn rem(self, other: u8) -> u8 {
        self % other
    }
}
impl Rem for i8 {
    fn rem(self, other: i8) -> i8 {
        self % other
    }
}
impl Rem for i16 {
    fn rem(self, other: i16) -> i16 {
        self % other
    }
}
impl Rem for i32 {
    fn rem(self, other: i32) -> i32 {
        self % other
    }
}
impl Rem for i64 {
    fn rem(self, other: i64) -> i64 {
        self % other
    }
}

/// The unary `-` operator.
///
/// Implemented for [`Field`] and the signed integer types. Negating a field element gives its
/// additive inverse modulo the field's prime. Negating the minimum value of a signed type fails,
/// because the result doesn't fit.
///
/// Example:
///
/// ```noir
/// assert_eq(-(5_i8), -5);
///
/// // Negating a field element gives its additive inverse.
/// let x: Field = 3;
/// assert_eq(-x + x, 0);
/// ```
///
/// Negating the minimum value of a signed type fails:
///
/// ```noir should_fail
/// // Fails: 128 doesn't fit in an `i8`.
/// let _ = -i8::min_value();
/// ```
// docs:start:neg-trait
pub trait Neg {
    /// Returns `-self`.
    fn neg(self) -> Self;
}
// docs:end:neg-trait

// docs:start:neg-trait-impls
impl Neg for Field {
    fn neg(self) -> Field {
        -self
    }
}

impl Neg for i8 {
    fn neg(self) -> i8 {
        -self
    }
}
impl Neg for i16 {
    fn neg(self) -> i16 {
        -self
    }
}
impl Neg for i32 {
    fn neg(self) -> i32 {
        -self
    }
}
impl Neg for i64 {
    fn neg(self) -> i64 {
        -self
    }
}
// docs:end:neg-trait-impls

/// `+` that wraps around instead of failing on overflow.
///
/// For the integer types the result is computed modulo `2^N`, where `N` is the type's bit size; for
/// signed types this is the two's complement result. For [`Field`] it is the same as `+`.
///
/// Example:
///
/// ```noir
/// use std::ops::WrappingAdd;
///
/// assert_eq(255_u8.wrapping_add(1), 0);
/// assert_eq(127_i8.wrapping_add(1), -128);
/// ```
// docs:start:wrapping-add-trait
pub trait WrappingAdd {
    /// Returns `self + y`, wrapping around on overflow.
    fn wrapping_add(self, y: Self) -> Self;
}
// docs:end:wrapping-add-trait

impl WrappingAdd for u8 {
    fn wrapping_add(self: u8, y: u8) -> u8 {
        wrapping_add_hlp(self, y)
    }
}

impl WrappingAdd for u16 {
    fn wrapping_add(self: u16, y: u16) -> u16 {
        wrapping_add_hlp(self, y)
    }
}

impl WrappingAdd for u32 {
    fn wrapping_add(self: u32, y: u32) -> u32 {
        wrapping_add_hlp(self, y)
    }
}

impl WrappingAdd for u64 {
    fn wrapping_add(self: u64, y: u64) -> u64 {
        wrapping_add_hlp(self, y)
    }
}

impl WrappingAdd for u128 {
    fn wrapping_add(self: u128, y: u128) -> u128 {
        wrapping_add_hlp(self, y)
    }
}

impl WrappingAdd for i8 {
    fn wrapping_add(self: i8, y: i8) -> i8 {
        let x = self as u8;
        x.wrapping_add(y as u8) as i8
    }
}

impl WrappingAdd for i16 {
    fn wrapping_add(self: i16, y: i16) -> i16 {
        let x = self as u16;
        x.wrapping_add(y as u16) as i16
    }
}

impl WrappingAdd for i32 {
    fn wrapping_add(self: i32, y: i32) -> i32 {
        let x = self as u32;
        x.wrapping_add(y as u32) as i32
    }
}

impl WrappingAdd for i64 {
    fn wrapping_add(self: i64, y: i64) -> i64 {
